"""Collect scoped typed operation records from the kernel receipts of this run; every listed proof must have a receipt."""
from pathlib import Path
import json
B=Path(__file__).resolve().parents[1]
def load(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def save(p,v):Path(p).write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
G='BornFable.GaussRat.';H='BornFable.HermitianCarrier.';P='BornFable.HermitianPsd.'
RECORDS=[
 ('GH-01','Gaussian rationals as a concrete ring with star, Q-algebra and field structure','Pairs (re, im) of rationals','CommRing, StarRing, Algebra Q, Field, Nontrivial, CharZero instances and componentwise evaluation lemmas',[G+n for n in ['instCommRing','instStarRing','instAlgebra','instField','instNontrivial','instCharZero','re_zero','im_zero','re_one','im_one','re_add','im_add','re_neg','im_neg','re_sub','im_sub','re_mul','im_mul','re_smul','im_smul','re_nsmul','im_nsmul','re_zsmul','im_zsmul','re_star','im_star','re_I','im_I','re_natCast','im_natCast','re_intCast','im_intCast','re_ratCast','im_ratCast','re_ofNat','im_ofNat','re_ofRat','im_ofRat','re_algebraMap','im_algebraMap','re_inv','im_inv','smul_mk','mk_eq_add_mul_I','I_mul_I','star_I','algebraMap_eq_ratCast','reAddMonoidHom_apply','imAddMonoidHom_apply','re_sum','im_sum','inv_zero','mul_inv_cancel']]),
 ('GH-02','Norm and conjugation positivity on Q(i)','A Gaussian rational z (and w)','normSq z >= 0 with equality iff z = 0; star z * z = normSq z; real/imaginary parts of star z * w',[G+n for n in ['normSq_nonneg','normSq_eq_zero_iff','normSq_mul','normSq_natCast','star_mul_self','re_star_mul_self','im_star_mul_self','re_star_mul','im_star_mul','re_star_mul_comm','im_star_mul_comm','re_smul_rat','re_algebraMap_mul']]),
 ('GH-03','Hermitian form and vector norm','Gaussian-rational n x n matrix A and vector x','hf A x = re(x* A x) is Q-linear in A; vnorm x = sum normSq (x i) is positive off zero; hf 1 x = vnorm x',[H+n for n in ['vnorm','vnorm_nonneg','vnorm_eq_zero_iff','vnorm_zero','vnorm_pos','normSq_le_vnorm','hf','hf_add','hf_sub','hf_neg','hf_smul','hf_zero','hf_one','hf_eq_sum_sum']]),
 ('GH-04','Carrier preorder and effects over Q(i)','All Gaussian-rational n x n matrices; unit = identity','OrderedQUnit instance with A <= B iff PsdH (B - A); effects are 0 <= hf E x <= vnorm x; the order is a preorder only',[H+n for n in ['PsdH','space','space_le','space_u','effect_iff',"effect_iff'"]]),
 ('GH-05','Order-unit bound on Gaussian-rational matrices','Any Gaussian-rational matrix A','|hf A x| <= (sum (|re A i j| + |im A i j|)) * vnorm x; natural bound k with -(k * 1) <= A <= k * 1',[H+n for n in ['re_star_mul_mul_le','abs_hf_le','order_unit']]),
 ('GH-06','Rank-one effects by complex Cauchy-Schwarz','Nonzero Gaussian-rational vector x','normSq (x* y) <= vnorm x * vnorm y; P x = x x* / vnorm x is an effect',[H+n for n in ['star_dot_eq_sum','dot_vecMulVec_star','hf_vecMulVec_star','normSq_dot_le','P','hf_rankOne','rankOne_effect']]),
 ('GH-07','Real-part trace representation of Q-linear functionals','Q-linear (real-valued) L on Gaussian-rational n x n matrices','L A = re trace (repMatrix L * A) with repMatrix L j i = (L(single i j 1), -L(single i j I)); the representing matrix is unique; hf rho x = re trace (rho * x x*)',[H+n for n in ['repMatrix','repMatrix_apply','repMatrix_re','repMatrix_im','trace_mul_eq_sum','re_trace_mul','single_eq_smul_add_smul','trace_rep','re_trace_mul_single_one','re_trace_mul_single_I','rep_unique','dot_eq_trace','hf_eq_re_trace']]),
 ('GH-08','Hermitian part and skew-Hermitian null elements','Matrix A; Hermitian rho','hf A^H x = hf A x; re trace (rho * E^H) = re trace (rho * E) for Hermitian rho; skew-Hermitian matrices are null in the preorder',[H+n for n in ['star_dot_mulVec','hf_conjTranspose','re_trace_mul_conjTranspose','hf_eq_zero_of_skew','skew_le_zero_and_ge']]),
 ('GH-10','Born representation over Q(i)','Effect valuation W on Gaussian-rational n x n matrices','Unique rho with W.v E = re trace (rho * E) on effects; rho Hermitian, PSD over Q(i), trace one; v (P x) = hf rho x / vnorm x',[H+n for n in ['space_isOrderUnit','ext_effect','ext_one','ext_nonneg','ext_eq_re_trace','density_effect','density_re_trace','density_psd','ext_skew_zero','single_conjTranspose','single_neg_eq','skew_single_sub','skew_single_I_add','density_hermitian','density_trace','traceWith_apply','density_unique','born_representation','density_is_state','born_rule']]),
 ('GH-11','Converse for every state and nonvacuity over Q(i)','Hermitian rational-PSD trace-one rho; arbitrary effect E; the pure state e0','re trace (rho * E) >= 0 via the Hermitian part; the Born valuation of rho has density rho; densities have Hermitian Gram form; pureZero exists in every dimension n+1',[H+n for n in ['ofState_density','re_trace_mul_nonneg_of_effect','bornValuation_apply','bornValuation_density','state_valuation_correspondence','density_hasGram','re_trace_single_zero_mul','re_apply_zero_zero_eq_hf','pureZero_apply','pureZero_density']]),
]
def collect(extra=()):
    by={e['name']:e for e in load(B/'verification/kernel_axioms.json')['printed_receipts']};records=[]
    for id_,name,inputs,result,proofs in sorted(list(RECORDS)+list(extra),key=lambda r:r[0]):
        missing=[p for p in proofs if p not in by]
        if missing:raise RuntimeError('No receipt for '+', '.join(missing))
        records.append({'id':id_,'name':name,'inputs':inputs,'output_or_relation':result,'status':'KERNEL_CHECKED_TYPED_OPERATION','admissible_substitution':'Substitute only matching carrier types and supply every displayed binder; the matrix order is a preorder, not a partial order; valuations are real-valued and Q-linear.','proofs':[by[p] for p in proofs]})
    save(B/'operad_delta.json',{'schema_version':2,'namespace':'GH-GAUSSIAN-HERMITIAN','records':records,'formal_operad_claim':'Scoped typed operations with kernel-checked relations and exact receipts; no complete higher-arity operad is claimed.','authority_effect':'None'})
    print(json.dumps({'records':len(records),'proofs':sum(len(r['proofs']) for r in records)}))
if __name__=='__main__':
    extra=json.loads((B/'tools/operad_extra.json').read_text(encoding='utf-8')) if (B/'tools/operad_extra.json').is_file() else []
    collect([tuple(e) for e in extra])
